#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float hatch_density;   // 0.5..3.0 lines scale
    float line_thickness;  // 0.5..3.0
    float edge_emphasis;   // 0..2
    float paper_mix;       // 0..1
    float ink_r;           // Ink R
    float ink_g;           // Ink G
    float ink_b;           // Ink B
    float paper_r;         // Paper R
    float paper_g;         // Paper G
    float paper_b;         // Paper B
};

struct VIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VOut { float4 pos [[position]]; float2 uv; };

vertex VOut main0(VIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float luma(float3 c){ return dot(c, float3(0.2126,0.7152,0.0722)); }
static inline float radiansf(float deg){ return deg * (3.14159265358979323846/180.0); }

static inline float hatchPattern(float2 p, float density, float thickness, float angle){
    float2 d = float2(cos(angle), sin(angle));
    float v = fract(dot(p, d) * density);
    float line = smoothstep(0.5 - thickness, 0.5, v) * (1.0 - smoothstep(0.5, 0.5 + thickness, v));
    return line;
}

fragment float4 fragment_main(VOut in [[stage_in]], texture2d<float> src [[texture(0)]], constant Uniforms &u [[buffer(0)]]) {
    constexpr sampler s(address::clamp_to_edge, filter::linear);
    float2 pix = in.uv * u.OutputSize.xy;
    float3 c = src.sample(s, in.uv).rgb;
    float L = luma(c);

    // Edges
    float2 texel = 1.0 / u.OutputSize.xy;
    float gx=0.0, gy=0.0;
    float kx[9] = {-1,0,1,-2,0,2,-1,0,1};
    float ky[9] = {-1,-2,-1,0,0,0,1,2,1};
    int idx=0; for(int j=-1;j<=1;++j){ for(int i=-1;i<=1;++i){
        float3 s3 = src.sample(s, in.uv + float2(i,j)*texel).rgb;
        float Ll = luma(s3);
        gx += Ll * kx[idx]; gy += Ll * ky[idx]; idx++; }}
    float edge = smoothstep(0.25, 0.75, length(float2(gx,gy)));

    // Hatching density based on luminance
    float density = mix(0.5, 3.0, 1.0 - L) * clamp(u.hatch_density, 0.3, 4.0);
    float thick = clamp(u.line_thickness, 0.2, 3.0) * 0.08;

    // Multi-angle hatching
    float h0 = hatchPattern(pix, density,       thick, radiansf(0.0));
    float h1 = hatchPattern(pix, density*0.9,   thick, radiansf(45.0));
    float h2 = hatchPattern(pix, density*1.1,   thick, radiansf(90.0));
    float h3 = hatchPattern(pix, density*1.2,   thick, radiansf(135.0));

    // Combine by luminance tiers
    float ink = 0.0;
    ink = max(ink, step(0.85, 1.0 - L) * h0);
    ink = max(ink, step(0.65, 1.0 - L) * h1);
    ink = max(ink, step(0.45, 1.0 - L) * h2);
    ink = max(ink, step(0.25, 1.0 - L) * h3);

    // Emphasize edges
    ink = max(ink, edge * u.edge_emphasis);

    // Paper texture
    float noise = fract(sin(dot(pix, float2(12.9898,78.233))) * 43758.5453 + float(u.FrameCount)*0.017);
    float3 paperTint = float3(u.paper_r, u.paper_g, u.paper_b);
    float3 paper = mix(float3(1.0), paperTint, 0.2 + 0.2*noise);

    float3 outc = mix(c, paper, u.paper_mix);
    float3 inkColor = float3(u.ink_r, u.ink_g, u.ink_b);
    outc = mix(outc, inkColor, clamp(ink, 0.0, 1.0));

    return float4(saturate(outc), 1.0);
}

